import fs from 'node:fs'
import path from 'node:path'
import { GAME_BALANCE } from '../src/game3d/config/gameBalance.js'
import { computeSeasonOutcome, CRM_SUBSIDY_MODES } from '../src/game3d/config/economy.js'

const STRATEGIES = ['burn', 'happy_seeder', 'bale_sell', 'mulch', 'compost']
const MODES = ['none', 'individual_50', 'chc_80']
const SEASONS = 10
const ACRES = 5

const lines = [
  '# 10-Season Economy Balance Report (Honest Audit)',
  '',
  'Generated by `scripts/balance-sim.js` using `src/data/scenarios.json` and `src/game3d/config/economy.js`.',
  'Flags any strategy reaching `₹0` (cash insolvency) as **FAIL**, and compares CRM Subsidy **OFF (default)** vs **50% Individual** vs **80% CHC** (Sub-Mission on Agricultural Mechanization).',
  '',
  '## Summary Across CRM Subsidy Settings (10 Seasons, 5 Acres)',
  '',
  '| Subsidy Setting | Strategy | S1 Money | S5 Money | S10 Money | First ₹0 Season | Status |',
  '|---|---|---:|---:|---:|:---:|---|'
]

const modeSections = []
const summaryStats = {}

for (const modeKey of MODES) {
  const mode = CRM_SUBSIDY_MODES[modeKey]
  summaryStats[modeKey] = {}
  modeSections.push(`\n## Mode: ${mode.label} (\`${modeKey}\`)\n`)

  for (const strategy of STRATEGIES) {
    let state = { ...GAME_BALANCE.INITIAL_STATE, seasonIndex: 1, streak: 0 }
    let firstZeroSeason = null
    let cappedBeforeS8 = false
    let s1Money = 0
    let s5Money = 0
    const rows = []

    for (let s = 1; s <= SEASONS; s++) {
      state.seasonIndex = s
      const outcome = computeSeasonOutcome(strategy, state, { acres: ACRES, crmSubsidyMode: modeKey })
      state = {
        ...state,
        money: outcome.nextMoney,
        soilHealth: outcome.nextSoil,
        villageHealth: outcome.nextVillage,
        reputation: outcome.nextRep,
        streak: outcome.nextStreak
      }
      if (s === 1) s1Money = outcome.nextMoney
      if (s === 5) s5Money = outcome.nextMoney
      if (firstZeroSeason === null && outcome.nextMoney <= 0) {
        firstZeroSeason = s
      }
      if (s < 8 && outcome.nextSoil >= 100 && outcome.nextVillage >= 100 && outcome.nextRep >= 100) {
        cappedBeforeS8 = true
      }
      rows.push(
        `| S${s} | ₹${outcome.nextMoney.toLocaleString('en-IN')} | ${outcome.nextSoil} | ${outcome.nextVillage} | ${outcome.nextRep} | ${outcome.netSeasonBalance >= 0 ? '+' : ''}₹${outcome.netSeasonBalance.toLocaleString('en-IN')} | ${outcome.setback ? outcome.setback.label : 'None'} |`
      )
    }

    const status = firstZeroSeason !== null
      ? `❌ FAIL (hit ₹0 in S${firstZeroSeason})`
      : cappedBeforeS8
        ? '❌ FAIL (capped 100/100/100 before S8)'
        : '✅ PASS (solvent through S10)'

    summaryStats[modeKey][strategy] = { s1Money, s5Money, s10Money: state.money, firstZeroSeason, status }

    lines.push(
      `| ${mode.label} | \`${strategy}\` | ₹${s1Money.toLocaleString('en-IN')} | ₹${s5Money.toLocaleString('en-IN')} | ₹${state.money.toLocaleString('en-IN')} | ${firstZeroSeason ? `S${firstZeroSeason}` : 'Never'} | ${status} |`
    )

    modeSections.push(`### Strategy: \`${strategy}\` (${mode.label}) — ${status}`)
    modeSections.push('| Season | Money (₹) | Soil | Village | Reputation | Net Season (₹) | Setback |')
    modeSections.push('| :---: | ---: | ---: | ---: | ---: | ---: | :--- |')
    modeSections.push(...rows)
    modeSections.push('')
  }
}

lines.push(
  '',
  '## Game Designer Decisions Required',
  '',
  'Because the simulation uses real-world cost/yield estimates without invented numbers, several strategies hit `₹0` under default (unsubsidized) costs:',
  '1. **Default Subsidy Setting**: Decide whether the game should keep CRM machinery subsidy **Off** by default (showing real unsubsidized cash pressure) or expose a prominent mid-game policy toggle (**50% Individual** / **80% CHC**).',
  '2. **Insolvency (`₹0`) Handling**: Decide what happens when a player hits `₹0` (e.g., Burn in S4, Happy Seeder in S5 without subsidy, Mulch in S9 without subsidy) — emergency credit/loan, season failure screen, or co-op rental fallback.',
  '3. **Base Crop Yield vs Operating Cost**: Decide whether 5-acre grain revenue (`baseRevenue = ₹19,500`) vs recurring operating cost (`₹8,500 + ₹300*(s-1)`) plus setbacks (`-₹2,400` / `-₹3,200`) should be tuned so sustainable options remain cash-positive without subsidy.',
  '4. **Bale & Sell Dominance**: `bale_sell` avoids upfront machinery hire and reaches ~₹61k by S10 while `compost` reaches ~₹31k; decide whether repeated straw removal should carry a stronger long-term organic-matter penalty or transport risk.'
)

const outPath = path.resolve('docs/BALANCE_REPORT.md')
fs.writeFileSync(outPath, [...lines, ...modeSections].join('\n'), 'utf8')
console.log(`Wrote ${outPath}`)
console.log('SUMMARY_JSON:', JSON.stringify(summaryStats))
